export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = {},
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdsEntries = Object.entries(thresholds);
  const thresholdsResult = thresholdsEntries.map(([metricId, minScore]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= minScore;
    return {
      metric: metricId,
      min: minScore,
      score: score ?? null,
      passed
    };
  });

  const allPassed = thresholdsResult.length === 0 || thresholdsResult.every((t) => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdsEntries.length > 0) {
    report.passed = allPassed;
    report.thresholds = thresholdsResult;
  }

  return report;
}

